CREATE OR REPLACE FUNCTION truss.capacity_reserve_original(issued_ordinal bigint, context_bytes bytea, plan_bytes bytea, row_budget bigint, byte_budget bigint, layout_bytes bytea, resource_bytes bytea)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  actual_xid xid8;
  ledger truss.row_home_capacity%ROWTYPE;
  head_revision integer;
BEGIN
  IF issued_ordinal IS NULL OR issued_ordinal < 0
    OR context_bytes IS NULL OR octet_length(context_bytes) NOT BETWEEN 1 AND 1048576
    OR plan_bytes IS NULL OR octet_length(plan_bytes) NOT BETWEEN 1 AND 8388608
    OR octet_length(context_bytes) + octet_length(plan_bytes) > 8388608
    OR row_budget IS NULL OR row_budget NOT BETWEEN 1 AND 65536
    OR byte_budget IS NULL OR byte_budget NOT BETWEEN 1 AND 536870912
    OR layout_bytes IS NULL OR resource_bytes IS NULL THEN
    RAISE EXCEPTION 'original bounded reservation inputs required' USING ERRCODE='22023';
  END IF;
  actual_xid := pg_current_xact_id_if_assigned();
  IF actual_xid IS NULL THEN
    RAISE EXCEPTION 'original assigned transaction required' USING ERRCODE='55000';
  END IF;
  -- The original producer must enter before every lower policy/key/owner lock.
  SELECT h.rev INTO STRICT head_revision FROM truss.schema_head h WHERE h.id=1 FOR SHARE;
  SELECT c.* INTO STRICT ledger FROM truss.row_home_capacity c WHERE c.singleton_id=1 FOR UPDATE;
  IF ledger.original_layout_bytes IS DISTINCT FROM layout_bytes
    OR ledger.original_resource_profile_bytes IS DISTINCT FROM resource_bytes
    OR ledger.reservation_writer_xid IS NOT NULL THEN
    RAISE EXCEPTION 'original available ledger/profile required' USING ERRCODE='55000';
  END IF;
  IF EXISTS (SELECT 1 FROM truss.row_home_operation o WHERE o.original_writer_xid=actual_xid
      AND (o.phase <> 'application_finalized' OR o.operation_ordinal >= issued_ordinal)) THEN
    RAISE EXCEPTION 'original issued operation frontier required' USING ERRCODE='55000';
  END IF;
  -- Subtract before adding: no overflowing trial sum or capacity eviction.
  IF row_budget > 65536-ledger.retained_rows
    OR byte_budget > 536870912-ledger.retained_custody_bytes THEN
    RAISE EXCEPTION 'original capacity unavailable' USING ERRCODE='54000';
  END IF;
  UPDATE truss.row_home_capacity SET reserved_rows=row_budget,reserved_custody_bytes=byte_budget,
    reservation_writer_xid=actual_xid,reservation_operation_ordinal=issued_ordinal,
    reservation_context_bytes=context_bytes,reservation_plan_bytes=plan_bytes,
    reservation_initial_rows=row_budget,reservation_initial_custody_bytes=byte_budget
  WHERE singleton_id=1;
END;
$function$

CREATE OR REPLACE FUNCTION truss.capacity_transfer_original(context_bytes bytea, plan_bytes bytea, new_rows bigint, positive_growth_bytes bigint, removed_bytes bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  actual_xid xid8;
  ledger truss.row_home_capacity%ROWTYPE;
  operation truss.row_home_operation%ROWTYPE;
BEGIN
  IF new_rows IS NULL OR new_rows < 0 OR positive_growth_bytes IS NULL OR positive_growth_bytes < 0
    OR removed_bytes IS NULL OR removed_bytes < 0
    OR positive_growth_bytes < new_rows
    OR context_bytes IS NULL OR octet_length(context_bytes) NOT BETWEEN 1 AND 1048576
    OR plan_bytes IS NULL OR octet_length(plan_bytes) NOT BETWEEN 1 AND 8388608
    OR octet_length(context_bytes)+octet_length(plan_bytes)>8388608 THEN
    RAISE EXCEPTION 'original nonnegative event deltas required' USING ERRCODE='22023';
  END IF;
  actual_xid := pg_current_xact_id_if_assigned();
  IF actual_xid IS NULL THEN RAISE EXCEPTION 'original assigned transaction required' USING ERRCODE='55000'; END IF;
  -- No FOR UPDATE: the original reserve UPDATE already owns the ledger through
  -- termination. Observers cannot acquire an earlier capacity lock here.
  SELECT c.* INTO STRICT ledger FROM truss.row_home_capacity c WHERE c.singleton_id=1;
  IF ledger.reservation_writer_xid IS DISTINCT FROM actual_xid
    OR ledger.reservation_context_bytes IS DISTINCT FROM context_bytes
    OR ledger.reservation_plan_bytes IS DISTINCT FROM plan_bytes THEN
    RAISE EXCEPTION 'original held reservation required' USING ERRCODE='55000';
  END IF;
  -- Unique unfinished scope, not latest ordinal or a caller-selected operation.
  SELECT o.* INTO STRICT operation FROM truss.row_home_operation o
  WHERE o.original_writer_xid=actual_xid AND o.phase <> 'application_finalized';
  IF operation.operation_ordinal IS DISTINCT FROM ledger.reservation_operation_ordinal
    OR operation.original_context_bytes IS DISTINCT FROM ledger.reservation_context_bytes THEN
    RAISE EXCEPTION 'original operation/reservation correspondence required' USING ERRCODE='55000';
  END IF;
  IF new_rows > ledger.reserved_rows OR positive_growth_bytes > ledger.reserved_custody_bytes
    OR removed_bytes > ledger.retained_custody_bytes THEN
    RAISE EXCEPTION 'original event capacity unavailable' USING ERRCODE='54000';
  END IF;
  -- Producer independently derives complete OLD/NEW membership and exact row/
  -- carrier/overhead deltas; arithmetic cannot authenticate these supplied deltas.
  UPDATE truss.row_home_capacity
  SET retained_rows=retained_rows+new_rows,
    retained_custody_bytes=retained_custody_bytes-removed_bytes+positive_growth_bytes,
    reserved_rows=reserved_rows-new_rows,
    reserved_custody_bytes=reserved_custody_bytes-positive_growth_bytes
  WHERE singleton_id=1;
  -- Shrink never refunds remaining capacity. Immutable initial budgets remain.
END;
$function$

CREATE OR REPLACE FUNCTION truss.capacity_release_original(context_bytes bytea, plan_bytes bytea)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  actual_xid xid8;
  ledger truss.row_home_capacity%ROWTYPE;
  operation truss.row_home_operation%ROWTYPE;
BEGIN
  IF context_bytes IS NULL OR octet_length(context_bytes) NOT BETWEEN 1 AND 1048576
    OR plan_bytes IS NULL OR octet_length(plan_bytes) NOT BETWEEN 1 AND 8388608
    OR octet_length(context_bytes)+octet_length(plan_bytes)>8388608 THEN
    RAISE EXCEPTION 'original bounded release inputs required' USING ERRCODE='22023';
  END IF;
  actual_xid := pg_current_xact_id_if_assigned();
  IF actual_xid IS NULL THEN RAISE EXCEPTION 'original assigned transaction required' USING ERRCODE='55000'; END IF;
  SELECT c.* INTO STRICT ledger FROM truss.row_home_capacity c WHERE c.singleton_id=1;
  IF ledger.reservation_writer_xid IS DISTINCT FROM actual_xid
    OR ledger.reservation_context_bytes IS DISTINCT FROM context_bytes
    OR ledger.reservation_plan_bytes IS DISTINCT FROM plan_bytes THEN
    RAISE EXCEPTION 'original held reservation required' USING ERRCODE='55000';
  END IF;
  SELECT o.* INTO STRICT operation FROM truss.row_home_operation o
  WHERE o.original_writer_xid=actual_xid AND o.operation_ordinal=ledger.reservation_operation_ordinal;
  IF operation.phase <> 'application_finalized'
    OR operation.original_context_bytes IS DISTINCT FROM ledger.reservation_context_bytes THEN
    RAISE EXCEPTION 'original finalized operation required' USING ERRCODE='55000';
  END IF;
  IF EXISTS (SELECT 1 FROM truss.row_home_operation o
      WHERE o.original_writer_xid=actual_xid AND o.phase <> 'application_finalized') THEN
    RAISE EXCEPTION 'unfinished transaction scope cannot release reservation' USING ERRCODE='55000';
  END IF;
  -- Full protected finalizer establishes complete original guards/results; phase
  -- CHECKs alone do not confer it. Release only remaining, never initial totals.
  UPDATE truss.row_home_capacity SET reserved_rows=0,reserved_custody_bytes=0,
    reservation_writer_xid=NULL,reservation_operation_ordinal=NULL,
    reservation_context_bytes=NULL,reservation_plan_bytes=NULL,
    reservation_initial_rows=NULL,reservation_initial_custody_bytes=NULL
  WHERE singleton_id=1;
END;
$function$

CREATE OR REPLACE FUNCTION truss.custody_codec_columns_original(kind text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  target regclass;
  expected_names text[];
  expected_types oid[];
  expected_required boolean[];
  names text[]; types oid[]; required boolean[]; modifiers integer[];
BEGIN
  IF current_setting('server_encoding') <> 'UTF8' THEN
    RAISE EXCEPTION 'original UTF8 custody image required' USING ERRCODE='55000';
  END IF;
  IF kind='operation' THEN
    target := 'truss.row_home_operation'::regclass;
    expected_names := ARRAY['original_writer_xid','operation_ordinal','operation_kind','phase',
      'effect_generation','readiness_generation','sealed_generation','application_generation',
      'original_context_bytes','original_definition_bytes','original_input_bytes','original_prestate_bytes',
      'admitted_candidate_bytes','effect_obligation_bytes','original_group_custody_bytes','application_result_bytes'];
    expected_types := ARRAY['xid8'::regtype::oid,'int8'::regtype::oid,'text'::regtype::oid,'text'::regtype::oid,
      'int8'::regtype::oid,'int8'::regtype::oid,'int8'::regtype::oid,'int8'::regtype::oid,
      'bytea'::regtype::oid,'bytea'::regtype::oid,'bytea'::regtype::oid,'bytea'::regtype::oid,
      'bytea'::regtype::oid,'bytea'::regtype::oid,'bytea'::regtype::oid,'bytea'::regtype::oid];
    expected_required := ARRAY[true,true,true,true,true,false,false,false,true,true,true,true,true,true,true,false];
  ELSIF kind='touch' THEN
    target := 'truss.row_home_touch'::regclass;
    expected_names := ARRAY['transaction_id','owner_kind','owner_id','owner_discriminator_id',
      'property_owner_type_id','property_id','dirty_generation','sealed_generation',
      'original_layout_bytes','original_home_bytes','original_owner_property_bytes','original_operation_bytes'];
    expected_types := ARRAY['xid8'::regtype::oid,'text'::regtype::oid,'int8'::regtype::oid,'int4'::regtype::oid,
      'int4'::regtype::oid,'int4'::regtype::oid,'int8'::regtype::oid,'int8'::regtype::oid,
      'bytea'::regtype::oid,'bytea'::regtype::oid,'bytea'::regtype::oid,'bytea'::regtype::oid];
    expected_required := ARRAY[true,true,true,true,true,true,true,false,true,true,true,true];
  ELSE
    RAISE EXCEPTION 'original custody kind required' USING ERRCODE='22023';
  END IF;
  -- Include dropped/user columns: new, removed or replaced fields cannot vanish
  -- from accounting. This does not verify CHECKs/defaults/triggers/ACL/authority.
  SELECT array_agg(a.attname::text ORDER BY a.attnum),array_agg(a.atttypid ORDER BY a.attnum),
    array_agg(a.attnotnull ORDER BY a.attnum),array_agg(a.atttypmod ORDER BY a.attnum)
  INTO names,types,required,modifiers FROM pg_attribute a WHERE a.attrelid=target AND a.attnum>0;
  IF names IS DISTINCT FROM expected_names OR types IS DISTINCT FROM expected_types
    OR required IS DISTINCT FROM expected_required
    OR modifiers IS DISTINCT FROM array_fill(-1,ARRAY[cardinality(expected_names)]) THEN
    RAISE EXCEPTION 'original complete custody column profile required' USING ERRCODE='55000';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.custody_frame_original(kind text, cells bytea[])
 RETURNS bytea
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  expected_count integer;
  prefix bytea;
  item bytea;
  total bigint;
  result bytea;
BEGIN
  IF kind='operation' THEN expected_count:=16;
  ELSIF kind='touch' THEN expected_count:=12;
  ELSE RAISE EXCEPTION 'original custody kind required' USING ERRCODE='22023'; END IF;
  IF cells IS NULL OR array_ndims(cells) IS DISTINCT FROM 1
    OR array_lower(cells,1) IS DISTINCT FROM 1 OR cardinality(cells)<>expected_count THEN
    RAISE EXCEPTION 'complete ordered custody cells required' USING ERRCODE='22023';
  END IF;
  prefix:=convert_to('truss.custody.'||kind||'/0.1','UTF8')||decode('00','hex')||int2send(expected_count::smallint);
  total:=octet_length(prefix);
  FOREACH item IN ARRAY cells LOOP
    total:=total+9+coalesce(octet_length(item),0)::bigint;
    IF total>8388608 THEN RAISE EXCEPTION 'complete custody row bound' USING ERRCODE='54000'; END IF;
  END LOOP;
  -- Complete size preflight precedes frame construction. This bounds output,
  -- not native composite argument materialization or repeated copy work.
  result:=prefix;
  FOREACH item IN ARRAY cells LOOP
    IF item IS NULL THEN result:=result||decode('00','hex')||int8send(0);
    ELSE result:=result||decode('01','hex')||int8send(octet_length(item)::bigint)||item; END IF;
  END LOOP;
  RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION truss.custody_size_original(kind text, lengths integer[])
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE expected_count integer; item integer; total bigint;
BEGIN
  IF kind='operation' THEN expected_count:=16;
  ELSIF kind='touch' THEN expected_count:=12;
  ELSE RAISE EXCEPTION 'original custody kind required' USING ERRCODE='22023'; END IF;
  IF lengths IS NULL OR array_ndims(lengths) IS DISTINCT FROM 1
    OR array_lower(lengths,1) IS DISTINCT FROM 1 OR cardinality(lengths)<>expected_count THEN
    RAISE EXCEPTION 'complete ordered custody lengths required' USING ERRCODE='22023';
  END IF;
  total:=octet_length(convert_to('truss.custody.'||kind||'/0.1','UTF8'))+3;
  FOREACH item IN ARRAY lengths LOOP
    IF item<0 THEN RAISE EXCEPTION 'nonnegative original custody length required' USING ERRCODE='22023'; END IF;
    total:=total+9+coalesce(item,0)::bigint;
    IF total>8388608 THEN RAISE EXCEPTION 'complete custody row bound' USING ERRCODE='54000'; END IF;
  END LOOP;
  RETURN total;
END;
$function$

CREATE OR REPLACE FUNCTION truss.capacity_operation_observe_original()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE ledger truss.row_home_capacity%ROWTYPE; old_size bigint:=0; new_size bigint; added bigint:=0;
BEGIN
  IF TG_RELID<>'truss.row_home_operation'::regclass OR TG_OP NOT IN ('INSERT','UPDATE')
    OR (TG_OP='INSERT' AND TG_WHEN<>'AFTER') OR (TG_OP='UPDATE' AND TG_WHEN<>'BEFORE') THEN
    RAISE EXCEPTION 'original operation capacity event required' USING ERRCODE='55000';
  END IF;
  SELECT c.* INTO STRICT ledger FROM truss.row_home_capacity c WHERE c.singleton_id=1;
  IF ledger.reservation_writer_xid IS DISTINCT FROM pg_current_xact_id_if_assigned()
    OR NEW.original_writer_xid IS DISTINCT FROM ledger.reservation_writer_xid
    OR NEW.operation_ordinal IS DISTINCT FROM ledger.reservation_operation_ordinal
    OR NEW.original_context_bytes IS DISTINCT FROM ledger.reservation_context_bytes THEN
    RAISE EXCEPTION 'original operation event/reservation correspondence required' USING ERRCODE='55000';
  END IF;
  IF TG_OP='INSERT' THEN added:=1;
  ELSE
    IF OLD.original_writer_xid IS DISTINCT FROM NEW.original_writer_xid
      OR OLD.operation_ordinal IS DISTINCT FROM NEW.operation_ordinal
      OR OLD.original_context_bytes IS DISTINCT FROM NEW.original_context_bytes
      OR OLD.phase='application_finalized' THEN
      RAISE EXCEPTION 'original unfinished operation update required' USING ERRCODE='55000';
    END IF;
    old_size:=truss.custody_operation_size_original(OLD);
  END IF;
  new_size:=truss.custody_operation_size_original(NEW);
  -- BEFORE UPDATE sees the original unfinished registry row during finalization.
  -- Other BEFORE triggers/dependencies must be closed and final parity verified.
  PERFORM truss.capacity_transfer_original(ledger.reservation_context_bytes,ledger.reservation_plan_bytes,
    added,greatest(new_size-old_size,0),greatest(old_size-new_size,0));
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION truss.capacity_touch_observe_original()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE ledger truss.row_home_capacity%ROWTYPE; old_size bigint:=0; new_size bigint; added bigint:=0;
BEGIN
  IF TG_RELID<>'truss.row_home_touch'::regclass OR TG_OP NOT IN ('INSERT','UPDATE')
    OR (TG_OP='INSERT' AND TG_WHEN<>'AFTER') OR (TG_OP='UPDATE' AND TG_WHEN<>'BEFORE') THEN
    RAISE EXCEPTION 'original touch capacity event required' USING ERRCODE='55000';
  END IF;
  SELECT c.* INTO STRICT ledger FROM truss.row_home_capacity c WHERE c.singleton_id=1;
  IF ledger.reservation_writer_xid IS DISTINCT FROM pg_current_xact_id_if_assigned()
    OR NEW.transaction_id IS DISTINCT FROM ledger.reservation_writer_xid THEN
    RAISE EXCEPTION 'original touch event/reservation correspondence required' USING ERRCODE='55000';
  END IF;
  IF TG_OP='INSERT' THEN added:=1;
  ELSE
    IF ROW(OLD.transaction_id,OLD.owner_kind,OLD.owner_id,OLD.owner_discriminator_id,OLD.property_owner_type_id,OLD.property_id)
      IS DISTINCT FROM ROW(NEW.transaction_id,NEW.owner_kind,NEW.owner_id,NEW.owner_discriminator_id,NEW.property_owner_type_id,NEW.property_id) THEN
      RAISE EXCEPTION 'original touch member identity required' USING ERRCODE='55000';
    END IF;
    old_size:=truss.custody_touch_size_original(OLD);
  END IF;
  new_size:=truss.custody_touch_size_original(NEW);
  PERFORM truss.capacity_transfer_original(ledger.reservation_context_bytes,ledger.reservation_plan_bytes,
    added,greatest(new_size-old_size,0),greatest(old_size-new_size,0));
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION truss.capacity_verify_inventory_original(layout_bytes bytea, resource_bytes bytea)
 RETURNS TABLE(observed_rows bigint, observed_custody_bytes bigint)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  ledger truss.row_home_capacity%ROWTYPE;
  operation truss.row_home_operation%ROWTYPE;
  touch truss.row_home_touch%ROWTYPE;
  revision integer;
  member_size bigint;
  targets oid[]:=ARRAY['truss.schema_head'::regclass::oid,'truss.row_home_capacity'::regclass::oid,
    'truss.row_home_operation'::regclass::oid,'truss.row_home_touch'::regclass::oid];
BEGIN
  IF layout_bytes IS NULL OR resource_bytes IS NULL THEN
    RAISE EXCEPTION 'original installation profiles required' USING ERRCODE='22023';
  END IF;
  -- Do not let owner bypass or FORCE RLS make a filtered inventory look complete.
  -- Physical identity, dependencies, triggers and write privileges remain external.
  IF EXISTS (SELECT 1 FROM pg_class c WHERE c.oid=ANY(targets)
      AND (c.relrowsecurity OR c.relforcerowsecurity OR c.relkind<>'r'))
    OR EXISTS (SELECT 1 FROM pg_inherits i WHERE i.inhrelid=ANY(targets) OR i.inhparent=ANY(targets)) THEN
    RAISE EXCEPTION 'original unfiltered noninherited inventory required' USING ERRCODE='55000';
  END IF;
  PERFORM truss.custody_codec_columns_original('operation');
  PERFORM truss.custody_codec_columns_original('touch');
  SELECT h.rev INTO STRICT revision FROM truss.schema_head h WHERE h.id=1 FOR SHARE;
  SELECT c.* INTO STRICT ledger FROM truss.row_home_capacity c WHERE c.singleton_id=1 FOR UPDATE;
  IF ledger.original_layout_bytes IS DISTINCT FROM layout_bytes
    OR ledger.original_resource_profile_bytes IS DISTINCT FROM resource_bytes THEN
    RAISE EXCEPTION 'original ledger profile correspondence required' USING ERRCODE='55000';
  END IF;
  observed_rows:=0; observed_custody_bytes:=0;
  -- No current-xid, phase, ordinal or caller-selected member filter.
  FOR operation IN SELECT o.* FROM truss.row_home_operation o LOOP
    member_size:=truss.custody_operation_size_original(operation);
    IF observed_rows>=65536 OR member_size>536870912-observed_custody_bytes THEN
      RAISE EXCEPTION 'complete retained inventory bound' USING ERRCODE='54000';
    END IF;
    observed_rows:=observed_rows+1; observed_custody_bytes:=observed_custody_bytes+member_size;
  END LOOP;
  FOR touch IN SELECT t.* FROM truss.row_home_touch t LOOP
    member_size:=truss.custody_touch_size_original(touch);
    IF observed_rows>=65536 OR member_size>536870912-observed_custody_bytes THEN
      RAISE EXCEPTION 'complete retained inventory bound' USING ERRCODE='54000';
    END IF;
    observed_rows:=observed_rows+1; observed_custody_bytes:=observed_custody_bytes+member_size;
  END LOOP;
  IF observed_rows IS DISTINCT FROM ledger.retained_rows
    OR observed_custody_bytes IS DISTINCT FROM ledger.retained_custody_bytes THEN
    RAISE EXCEPTION 'complete retained inventory/ledger parity required' USING ERRCODE='55000';
  END IF;
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION truss.capacity_commit_check_original(layout_bytes bytea, resource_bytes bytea)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE ledger truss.row_home_capacity%ROWTYPE;
BEGIN
  -- Full scope, original head/ledger exclusion and complete size/counter parity.
  PERFORM truss.capacity_verify_inventory_original(layout_bytes,resource_bytes);
  SELECT c.* INTO STRICT ledger FROM truss.row_home_capacity c WHERE c.singleton_id=1;
  IF ledger.reserved_rows<>0 OR ledger.reserved_custody_bytes<>0
    OR ledger.reservation_writer_xid IS NOT NULL
    OR ledger.reservation_operation_ordinal IS NOT NULL
    OR ledger.reservation_context_bytes IS NOT NULL
    OR ledger.reservation_plan_bytes IS NOT NULL
    OR ledger.reservation_initial_rows IS NOT NULL
    OR ledger.reservation_initial_custody_bytes IS NOT NULL THEN
    RAISE EXCEPTION 'original reservation must be released before commit' USING ERRCODE='55000';
  END IF;
  -- A persisted foreign unfinished row is not exempt from closeout. No repair,
  -- phase rewrite, capacity eviction or current-xid-only accounting here.
  IF EXISTS (SELECT 1 FROM truss.row_home_operation o WHERE o.phase<>'application_finalized') THEN
    RAISE EXCEPTION 'complete retained operation closeout required' USING ERRCODE='55000';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION truss.capacity_cache_invalidate_original()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE actual_xid xid8; memo truss.capacity_check_memo%ROWTYPE; next_generation bigint;
BEGIN
  IF TG_RELID<>'truss.row_home_capacity'::regclass OR TG_OP<>'UPDATE' OR TG_WHEN<>'AFTER' THEN
    RAISE EXCEPTION 'original capacity update required; deletion/truncation unavailable' USING ERRCODE='55000';
  END IF;
  actual_xid:=pg_current_xact_id_if_assigned();
  IF actual_xid IS NULL THEN RAISE EXCEPTION 'actual assigned capacity transaction required' USING ERRCODE='55000'; END IF;
  SELECT m.* INTO STRICT memo FROM truss.capacity_check_memo m WHERE m.singleton_id=1 FOR UPDATE;
  IF memo.writer_xid IS DISTINCT FROM actual_xid THEN next_generation:=1;
  ELSE
    IF memo.dirty_generation=9223372036854775807 THEN
      RAISE EXCEPTION 'original capacity generation exhausted' USING ERRCODE='54000';
    END IF;
    next_generation:=memo.dirty_generation+1;
  END IF;
  -- Even equal counter images invalidate. Memo updates do not change the ledger.
  UPDATE truss.capacity_check_memo SET writer_xid=actual_xid,
    dirty_generation=next_generation,verified_generation=NULL WHERE singleton_id=1;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION truss.capacity_cache_check_original()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE actual_xid xid8; memo truss.capacity_check_memo%ROWTYPE; layout_bytes bytea;resource_bytes bytea;
BEGIN
  IF TG_RELID<>'truss.capacity_check_memo'::regclass OR TG_OP<>'UPDATE' OR TG_WHEN<>'AFTER' THEN
    RAISE EXCEPTION 'original capacity memo callback required' USING ERRCODE='55000';
  END IF;
  actual_xid:=pg_current_xact_id_if_assigned();
  SELECT m.* INTO STRICT memo FROM truss.capacity_check_memo m WHERE m.singleton_id=1;
  IF actual_xid IS NULL OR memo.writer_xid IS DISTINCT FROM actual_xid THEN
    RAISE EXCEPTION 'original capacity memo transaction required' USING ERRCODE='55000';
  END IF;
  IF memo.verified_generation IS NOT DISTINCT FROM memo.dirty_generation THEN RETURN NULL; END IF;
  SELECT c.original_layout_bytes,c.original_resource_profile_bytes INTO STRICT layout_bytes,resource_bytes
    FROM truss.row_home_capacity c WHERE c.singleton_id=1;
  -- Stored profile equality is not independently registered profile authority.
  PERFORM truss.capacity_commit_check_original(layout_bytes,resource_bytes);
  UPDATE truss.capacity_check_memo SET verified_generation=dirty_generation WHERE singleton_id=1;
  RETURN NULL;
END;
